const PX = 450, PY = 316, PW = 570, PH = 504;
const SW = PW - 24, SH = PH - 24;               // phone screen size
const wt = (i) => W[i] - 0.05;
const tl_ = tl;
const mkd = R3.mk;
const FAINT = 'rgba(255,255,255,.55)';

/* ---------------- PHONE SHELL (settles with eased scale) ---------------- */
const shell = R3.card(PX, PY, PW, PH, null, { borderRadius: '56px', border: '4px solid rgba(255,255,255,.8)' });
R3.ft(shell, { autoAlpha: 0, scale: .9, y: 26 }, { autoAlpha: 1, scale: 1, y: 0, duration: .9, ease: 'power3.out' }, S);

const scr = mkd('div', 'r3-screen', { position: 'absolute', left: '12px', top: '12px', width: SW + 'px', height: SH + 'px',
  borderRadius: '44px 44px 40px 40px', background: '#0a0c11', overflow: 'hidden' }, shell);
scr.dataset.device = '1';
mkd('div', '', { position: 'absolute', left: (SW / 2 - 50) + 'px', top: '8px', width: '100px', height: '24px', borderRadius: '14px', background: '#000' }, scr);
R3.text(36, 8, '9:41', { size: 15, weight: 600, color: 'rgba(255,255,255,.7)', parent: scr }).style.lineHeight = '18px';
R3.text(SW - 36 - 70, 8, '5G', { size: 15, weight: 600, color: 'rgba(255,255,255,.7)', parent: scr, w: 70, align: 'right' }).style.lineHeight = '18px';

/* app bar: title + rolling count */
const bar = mkd('div', '', { position: 'absolute', left: '22px', top: '40px', height: '38px', display: 'flex', alignItems: 'baseline', gap: '10px', whiteSpace: 'nowrap' }, scr);
const barTitle = mkd('div', 'r3-t r3-el', { position: 'relative', left: '0', top: '0', fontSize: '28px', fontWeight: 700, color: '#fff', lineHeight: '36px' }, bar, 'Requests');
const barCnt = mkd('div', 'r3-t r3-el', { position: 'relative', left: '0', top: '0', fontSize: '28px', fontWeight: 600, color: FAINT, lineHeight: '36px' }, bar, '(38)');
const barRight = R3.text(SW - 22 - 110, 48, 'Hidden', { size: 19, weight: 600, color: 'rgba(120,180,255,.9)', parent: scr, w: 110, align: 'right' });
barRight.style.lineHeight = '24px';

/* skeleton placeholders under the rows (slots 0..5) */
const slotTop = (s) => 86 + s * 66;
const skels = [];
for (let s = 0; s < 6; s++) {
  const k = mkd('div', 'r3-el', { position: 'absolute', left: '16px', top: slotTop(s) + 'px', width: '514px', height: '58px' }, scr);
  mkd('div', '', { position: 'absolute', left: '13px', top: '9px', width: '40px', height: '40px', borderRadius: '50%', background: 'rgba(255,255,255,.06)' }, k);
  mkd('div', '', { position: 'absolute', left: '66px', top: '13px', width: '150px', height: '10px', borderRadius: '5px', background: 'rgba(255,255,255,.07)' }, k);
  mkd('div', '', { position: 'absolute', left: '66px', top: '33px', width: '280px', height: '9px', borderRadius: '5px', background: 'rgba(255,255,255,.05)' }, k);
  skels.push(k);
}

/* row factory */
function mkRow(d) {
  const row = mkd('div', 'r3-el', { position: 'absolute', left: '16px', top: slotTop(d.slot) + 'px', width: '514px', height: '58px',
    borderRadius: '14px', background: '#171b24', border: '1px solid rgba(255,255,255,.1)' }, scr);
  R3.avatar(12, 8, 40, d.k, row);
  const h = R3.text(64, 5, d.h, { size: 20, weight: 700, parent: row });
  const p = R3.text(64, 30, d.p, { size: 17, weight: 500, color: 'rgba(255,255,255,.64)', parent: row });
  const tm = R3.text(420, 8, d.t, { size: 15, weight: 500, color: 'rgba(255,255,255,.45)', parent: row, w: 78, align: 'right' });
  [h, p, tm].forEach((e) => { e.style.whiteSpace = 'nowrap'; });
  h.style.lineHeight = '24px'; p.style.lineHeight = '22px'; tm.style.lineHeight = '18px';
  const dot = mkd('div', 'r3-el', { position: 'absolute', left: '486px', top: '33px', width: '10px', height: '10px', borderRadius: '50%', background: '#3b9bff' }, row);
  let st = null;
  if (d.st) {
    st = R3.text(64, 30, d.st, { size: 17, weight: 600, color: 'rgba(255,255,255,.8)', parent: row });
    st.style.whiteSpace = 'nowrap'; st.style.lineHeight = '22px'; st.style.opacity = 0;
  }
  return { row, h, p, tm, dot, st };
}

const w1 = [
  mkRow({ slot: 0, h: '@mira.cuts', p: 'how do i blow up in a week??', t: '2m', k: 1 }),
  mkRow({ slot: 1, h: '@jayden.wav', p: 'day 3… 14 views 😩', t: '9m', k: 2, st: 'last active 6w ago' }),
  mkRow({ slot: 2, h: '@lexi.mp4', p: 'is there a faster way', t: '21m', k: 3, st: 'account deactivated' })
];
const kai = mkRow({ slot: 0, h: '@kai.makes', p: 'repost my page fam? 🙏', t: 'now', k: 4 });
const nova = mkRow({ slot: 1, h: '@nova.lux', p: '1 story share pls', t: 'now', k: 5 });
const tre = mkRow({ slot: 2, h: '@tre.visuals', p: "tag me, it'd change everything", t: 'now', k: 6 });

/* decline stamp (inside kai row) */
const stamp = mkd('div', 'r3-el', { position: 'absolute', left: '318px', top: '8px', padding: '3px 12px', border: '3px solid #ff4d5e', color: '#ff4d5e',
  background: 'rgba(255,77,94,.14)', borderRadius: '9px', fontSize: '22px', fontWeight: 800, letterSpacing: '1px', whiteSpace: 'nowrap', lineHeight: '28px' }, kai.row, '✕ Declined');

/* big avatar for the match cut (sits exactly over kai's row avatar) */
const big = R3.avatar(29, 95, 40, 4, scr);
tl_.set(big, { autoAlpha: 0 }, S);

/* profile bits that appear after the enlarge */
const pName = R3.text(0, 296, 'kai.makes', { size: 32, weight: 800, parent: scr, w: SW, align: 'center' });
const pSub = R3.text(0, 336, 'Edits · Tutorials', { size: 19, weight: 500, color: FAINT, parent: scr, w: SW, align: 'center' });
[pName, pSub].forEach((e) => { e.style.lineHeight = '1.2'; e.style.whiteSpace = 'nowrap'; });
const stats = [];
[['212', 'posts'], ['1.4K', 'followers'], ['389', 'following']].forEach((s, i) => {
  const n = R3.text(48 + i * 150, 384, s[0], { size: 30, weight: 800, parent: scr, w: 150, align: 'center' });
  const l = R3.text(48 + i * 150, 422, s[1], { size: 17, weight: 500, color: FAINT, parent: scr, w: 150, align: 'center' });
  n.style.lineHeight = '36px'; l.style.lineHeight = '22px';
  stats.push(n, l);
});

/* ---------------- LEFT COLUMN ---------------- */
// counter card (stays all section)
const cCard = R3.card(64, 680, 300, 130);
const cLab = R3.text(22, 14, 'Pending requests', { size: 20, weight: 600, color: FAINT, parent: cCard });
const cNum = R3.text(22, 44, '38', { size: 70, weight: 800, parent: cCard });
cLab.style.lineHeight = '24px'; cNum.style.lineHeight = '1';

// calendar card with 3 tiny squares
const cal = R3.card(64, 410, 300, 150);
const calT = R3.text(20, 16, 'Posting days', { size: 20, weight: 600, color: FAINT, parent: cal });
calT.style.lineHeight = '24px';
const squares = [];
let sq3 = null, sq3check = null, sq3hatch = null;
for (let i = 0; i < 3; i++) {
  const sq = mkd('div', 'r3-el', { position: 'absolute', left: (20 + i * 92) + 'px', top: '56px', width: '76px', height: '76px', borderRadius: '14px',
    border: '1.5px solid rgba(255,255,255,.22)', background: 'rgba(255,255,255,.07)' }, cal);
  const ck = mkd('div', '', { position: 'absolute', left: '0', top: '0', width: '100%', height: '100%', display: 'flex', alignItems: 'center',
    justifyContent: 'center', fontSize: '34px', color: 'rgba(255,255,255,.8)' }, sq, '✓');
  if (i === 2) {
    sq3 = sq; sq3check = ck;
    sq3hatch = mkd('div', '', { position: 'absolute', left: '0', top: '0', width: '100%', height: '100%', borderRadius: '12px', opacity: 0,
      background: 'repeating-linear-gradient(135deg, rgba(150,155,165,.55) 0px, rgba(150,155,165,.55) 6px, rgba(55,58,66,.65) 6px, rgba(55,58,66,.65) 12px)' }, sq);
  }
  squares.push(sq);
}

// "avg time to quit" chip
const qChip = mkd('div', 'r3-chip r3-el', { left: '64px', top: '322px', border: '1.5px solid rgba(255,255,255,.75)', background: 'rgba(255,255,255,.04)',
  color: '#fff', padding: '10px 20px', borderRadius: '999px', fontSize: '25px', fontWeight: 600, whiteSpace: 'nowrap', lineHeight: '32px' },
  null, 'avg time to quit: <b style="color:#ff5a6a">11 days</b>');

// inactive tally card (appears once accounts go grey)
const inact = R3.card(64, 586, 300, 64);
mkd('div', '', { position: 'absolute', left: '20px', top: '17px', width: '28px', height: '28px', borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #8a8f99, #4b4f58)', border: '2px solid #1a1d24' }, inact);
mkd('div', '', { position: 'absolute', left: '36px', top: '17px', width: '28px', height: '28px', borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #7a7f89, #3f434c)', border: '2px solid #1a1d24' }, inact);
const inT = R3.text(84, 14, '2 inactive', { size: 25, weight: 600, color: 'rgba(255,255,255,.85)', parent: inact });
inT.style.lineHeight = '32px'; inT.style.whiteSpace = 'nowrap';

/* ---------------- TIMELINE ---------------- */
// Row entrances use a small x offset (-10) so rows (left 16) never leave the phone screen.
const RX = -10;

// 0.00 major: phone settles (above); counter card + first row
R3.appear(cCard, 0.30, { y: 18, d: .55 });
R3.appear(w1[0].row, 0.16, { x: RX, y: 0, d: .45, scale: .98 });
R3.appear(w1[0].dot, 0.40, { y: 0, scale: .2, d: .3 });

// w1: row 2
R3.appear(w1[1].row, wt(1), { x: RX, y: 0, d: .45, scale: .98 });
R3.appear(w1[1].dot, wt(1) + .25, { y: 0, scale: .2, d: .3 });

// calendar group
R3.appear(cal, 0.50, { y: 16, d: .5 });
R3.appear(squares, 0.62, { y: 0, scale: .6, d: .4, stagger: .1 });

// w3: row 3 + quit chip
R3.appear(w1[2].row, wt(3), { x: RX, y: 0, d: .45, scale: .98 });
R3.appear(w1[2].dot, wt(3) + .25, { y: 0, scale: .2, d: .3 });
R3.appear(qChip, wt(3) + .06, { y: 10, scale: .9, d: .5 });

// grey-out events
function greyOut(r, t) {
  R3.ft(r.row, { filter: 'grayscale(0) brightness(1)' }, { filter: 'grayscale(1) brightness(.62)', duration: .45, ease: 'sine.inOut' }, t);
  tl_.to(r.p, { opacity: 0, duration: .18, ease: 'power1.in' }, t);
  tl_.to(r.dot, { opacity: 0, duration: .2 }, t);
  R3.ft(r.st, { opacity: 0, y: 5 }, { opacity: 1, y: 0, duration: .3, ease: 'power2.out' }, t + .2);
}
greyOut(w1[1], wt(8));                                   // w8
greyOut(w1[2], wt(12));                                  // w12
tl_.to(sq3check, { opacity: 0, duration: .2 }, wt(12));
tl_.to(sq3hatch, { opacity: 1, duration: .35, ease: 'power1.out' }, wt(12) + .05);
tl_.to(sq3, { borderColor: 'rgba(160,165,175,.6)', duration: .35 }, wt(12));

// inactive tally
R3.appear(inact, wt(13), { y: 14, d: .5 });

// camera: single eased step-in
ctx.cam.push(wt(16), 1.1, 1.06, -8, -8);

// left avatar stack + hairline connectors
function joinLeft(k, cy, t) {
  const a = R3.avatar(388, cy - 26, 52, k);
  R3.appear(a, t + .15, { x: -16, y: 0, scale: .6, d: .45 });
  const c = R3.connect([440, cy], [482, cy], t + .3, { color: 'rgba(255,255,255,.5)', w: 1.5, curve: 0, d: .35 });
  return { a, c };
}
function shift(rs, from, to, t, d) {
  rs.forEach((r) => R3.ft(r.row, { y: from }, { y: to, duration: d, ease: 'power3.out' }, t));
}

// w17: kai lands on top, wave 1 steps down
const t1 = wt(17);
shift(w1, 0, 66, t1, .4);
R3.appear(kai.row, t1 + .1, { y: -18, d: .5, scale: .97 });
R3.appear(kai.dot, t1 + .45, { y: 0, scale: .2, d: .3 });
const jk = joinLeft(4, 447, t1 + .1);

// w20: nova
const t2 = wt(20);
shift(w1, 66, 132, t2, .26);
R3.appear(nova.row, t2 + .08, { y: -18, d: .5, scale: .97 });
R3.appear(nova.dot, t2 + .4, { y: 0, scale: .2, d: .3 });
const jn = joinLeft(5, 513, t2 + .08);

// w22: tre + counters roll
const t3 = wt(22);
shift(w1, 132, 198, t3, .28);
R3.appear(tre.row, t3 + .08, { y: -18, d: .5, scale: .97 });
R3.appear(tre.dot, t3 + .4, { y: 0, scale: .2, d: .3 });
const jt = joinLeft(6, 579, t3 + .08);
R3.count(cNum, t3 + .1, .9, 38, 41);
R3.count(barCnt, t3 + .1, .9, 38, 41, { pre: '(', suf: ')' });

// w27: decline stamp on kai row
const t4 = wt(27);
R3.ft(stamp, { autoAlpha: 0, scale: 1.35, rotation: -14 }, { autoAlpha: 1, scale: 1, rotation: -5, duration: .4, ease: 'back.out(1.6)' }, t4);
tl_.to([kai.tm, kai.dot], { opacity: 0, duration: .2 }, t4);
tl_.to(kai.row, { borderColor: 'rgba(255,77,94,.75)', duration: .3 }, t4);

// match cut: kai avatar enlarges inside the phone, inbox clears behind it
const t5 = W[27] + .38;
tl_.fromTo(big, { autoAlpha: 1, x: 0, y: 0, scale: 1 }, { x: 224, y: 85, scale: 4.2, duration: 1.1, ease: 'power3.inOut', immediateRender: false }, t5);
const clear = [w1[0].row, w1[1].row, w1[2].row, kai.row, nova.row, tre.row].concat(skels);
tl_.to(clear, { autoAlpha: 0, duration: .4, ease: 'power2.in', stagger: .02 }, t5);
tl_.to([jn.a, jt.a, jn.c, jt.c], { opacity: .25, duration: .4, ease: 'sine.inOut' }, t5);

// profile details build under the enlarged avatar
R3.appear([pName, pSub], wt(30), { y: 10, d: .45, stagger: .08 });
R3.appear(stats, wt(32), { y: 8, d: .4, stagger: .06 });

