const T = (i, d = .05) => W[i] - d;
const DIM = 'rgba(255,255,255,.55)';
const abs = (x, y, w, h, extra) => Object.assign(R3.box(x, y, w, h), { position: 'absolute' }, extra || {});
const nw = (e) => { e.style.whiteSpace = 'nowrap'; e.style.fontVariantNumeric = 'tabular-nums'; return e; };
const se = (tag, attrs, parent) => {
  const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  parent.appendChild(e);
  return e;
};

/* Safe layout: the camera push scales the stage by 1.05 around its centre,
   so every element stays inside x 70..1016, y 316..812 before scaling. */

/* ---------------- PHONE + SCREEN ---------------- */
const ph = R3.card(300, 316, 480, 496, null, { borderRadius: '54px', border: '4px solid rgba(255,255,255,.8)' });
const scr = R3.mk('div', 'r3-screen', abs(12, 12, 456, 472, { overflow: 'hidden', borderRadius: '42px', background: '#0b0b0e' }), ph);
scr.dataset.device = '1';
const body = R3.mk('div', '', abs(0, 0, 456, 720, { zIndex: 1 }), scr);
const header = R3.mk('div', '', abs(0, 0, 456, 92, { zIndex: 5, background: '#0b0b0e', borderBottom: '1px solid rgba(255,255,255,.08)' }), scr);
R3.mk('div', '', abs(173, 8, 110, 28, { borderRadius: '16px', background: '#000' }), header);
const hdl = R3.text(0, 52, '@kai.makes', { size: 22, parent: header, w: 456, align: 'center', color: 'rgba(255,255,255,.8)', weight: 600 });
const pill = R3.chip(22, 46, 'Reposted by @bigstage · 2.1M', null, { red: true, parent: header });
Object.assign(pill.style, { position: 'absolute', width: '412px', height: '40px', lineHeight: '40px', padding: '0', textAlign: 'center', boxSizing: 'border-box',
  fontSize: '19px', fontWeight: '700', whiteSpace: 'nowrap', borderRadius: '20px', color: '#fff', background: 'linear-gradient(180deg,#ff5a6a,#e8283c)' });

/* profile block */
const av = R3.avatar(22, 104, 92, 1, body);
const stX = [138, 232, 330], stV = ['2', '0', '0'], stL = ['posts', 'followers', 'following'];
const stN = stX.map((x, i) => nw(R3.text(x, 108, stV[i], { size: 30, parent: body })));
const stT = stX.map((x, i) => R3.text(x, 154, stL[i], { size: 17, parent: body, color: DIM }));
const nameEl = nw(R3.text(22, 206, 'Kai Mendes', { size: 26, parent: body }));
const handEl = nw(R3.text(22, 246, '@kai.makes', { size: 19, parent: body, color: DIM, weight: 500 }));
const bioEl = nw(R3.text(22, 276, 'producer · ATL', { size: 19, parent: body, color: 'rgba(255,255,255,.85)', weight: 500 }));
const btnF = R3.mk('div', 'r3-el', abs(296, 206, 138, 38, { borderRadius: '12px', background: '#fff', color: '#0b0b0e', fontSize: '19px', fontWeight: '700', lineHeight: '38px', textAlign: 'center' }), body, 'Follow');
const btnM = R3.mk('div', 'r3-el', abs(296, 252, 138, 38, { borderRadius: '12px', background: 'rgba(255,255,255,.12)', color: '#fff', fontSize: '19px', fontWeight: '600', lineHeight: '38px', textAlign: 'center' }), body, 'Message');

/* tabs + divider */
const tabs = ['Posts', 'Reels', 'Tagged'].map((s, i) => R3.text(i * 152, 314, s, { size: 17, weight: 600, parent: body, w: 152, align: 'center', color: i ? DIM : '#fff' }));
const tabUL = R3.mk('div', 'r3-el', abs(56, 340, 40, 3, { background: '#fff', borderRadius: '2px', transformOrigin: '0 50%' }), body);
const divider = R3.mk('div', 'r3-el', abs(0, 346, 456, 1, { background: 'rgba(255,255,255,.1)' }), body);

/* grid: 4 x 3, two thumbs + ten dashed */
const CH = 112;
const cx = (c) => 22 + c * 104, cy = (r) => 352 + r * 118;
const posts = [{ l: 'Reel · Mar 2', v: '1,104 views' }, { l: 'Reel · Mar 19', v: '866 views' }];
const thumbs = posts.map((d, i) => {
  const th = R3.thumb(cx(i), cy(0), 98, CH, i, { parent: body, play: false });
  R3.mk('div', '', abs(0, 52, 98, 60, { background: 'linear-gradient(180deg,transparent,rgba(0,0,0,.7))', borderRadius: '0 0 10px 10px' }), th);
  nw(R3.text(7, 60, d.l, { size: 12, weight: 700, parent: th }));
  nw(R3.text(7, 84, d.v, { size: 12, weight: 500, color: 'rgba(255,255,255,.8)', parent: th }));
  return th;
});
const dashed = [];
for (let i = 2; i < 12; i++) {
  const c = i % 4, r = Math.floor(i / 4);
  const d = R3.mk('div', 'r3-el', abs(cx(c), cy(r), 98, CH, { borderRadius: '10px', boxSizing: 'border-box', border: '2px dashed rgba(255,255,255,.28)', background: 'rgba(255,255,255,.03)' }), body);
  dashed.push(d);
}
const plusG = dashed.map((d) => R3.text(0, 36, '+', { size: 34, weight: 500, parent: d, w: 98, align: 'center', color: 'rgba(255,255,255,.3)' }));
const ring = [0, 1].map((i) => R3.mk('div', 'r3-el', abs(cx(i) - 4, cy(0) - 4, 106, CH + 8, { border: '3px solid #fff', borderRadius: '13px', boxSizing: 'border-box', zIndex: 2 }), body));

/* ---------------- LEFT COLUMN ---------------- */
const cc = R3.card(70, 330, 210, 240);
R3.text(18, 16, 'Profile visits', { size: 19, parent: cc, color: DIM });
const cNum = nw(R3.text(18, 48, '0', { size: 48, weight: 800, parent: cc }));
const spW = R3.mk('div', 'r3-el', abs(18, 126, 174, 96), cc);
const spS = se('svg', { width: 174, height: 96, viewBox: '0 0 188 100', preserveAspectRatio: 'none', style: 'overflow:visible' }, spW);
se('line', { x1: 0, y1: 94, x2: 186, y2: 94, stroke: 'rgba(255,255,255,.22)', 'stroke-width': 2, 'stroke-dasharray': '3 6' }, spS);
const spArea = se('path', { d: 'M0 94 C 60 92, 110 84, 140 56 S 176 14, 186 6 L186 100 L0 100 Z', fill: 'rgba(255,255,255,.08)' }, spS);
const spLine = se('path', { d: 'M0 94 C 60 92, 110 84, 140 56 S 176 14, 186 6', fill: 'none', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linecap': 'round',
  pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 }, spS);
const spArrow = se('path', { d: 'M170 4 L186 4 L186 20', fill: 'none', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, spS);

const vLab = R3.text(70, 592, 'New visitors', { size: 17, color: DIM });
const vAv = [0, 1, 2, 3, 4, 5].map((i) => {
  const a = R3.avatar(70 + i * 30, 622, 44, i + 2);
  Object.assign(a.style, { border: '3px solid #121216', boxSizing: 'border-box' });
  return a;
});

const pc = R3.card(70, 700, 210, 100);
R3.text(18, 10, 'Posts', { size: 19, parent: pc, color: DIM });
const pNum = nw(R3.text(18, 36, '0', { size: 46, weight: 800, parent: pc }));
pNum.style.transformOrigin = '0% 60%';
R3.text(58, 56, '/ 12 slots', { size: 19, parent: pc, color: DIM });

/* ---------------- RIGHT COLUMN ---------------- */
const sc = R3.card(802, 330, 214, 92);
R3.avatar(16, 18, 56, 7, sc);
nw(R3.text(84, 20, '@bigstage', { size: 22, weight: 700, parent: sc }));
nw(R3.text(84, 54, '2.1M followers', { size: 16, parent: sc, color: DIM }));

const ac = R3.card(802, 452, 214, 148);
