const IR = { immediateRender: false };
const GOLD = '#ffd25a';
const mk = R3.mk;

/* ---------- local helpers ---------- */
const T = (x, y, html, size, o) => {
  o = o || {};
  const e = R3.text(x, y, html, { size, weight: o.weight || 700, color: o.color || '#fff', parent: o.parent, w: o.w, align: o.align || 'left' });
  e.style.whiteSpace = 'nowrap';
  e.style.position = 'absolute';
  e.style.lineHeight = (o.lh || Math.round(size * 1.15)) + 'px';
  if (o.ls) e.style.letterSpacing = o.ls;
  return e;
};
const sv = (tag, a, p) => { const e = document.createElementNS('http://www.w3.org/2000/svg', tag); for (const k in a) e.setAttribute(k, a[k]); p.appendChild(e); return e; };
const roll = (el, t, d, from, to, fmt, ease) => {
  const p = { v: from };
  tl.fromTo(p, { v: from }, { v: to, duration: d, ease: ease || 'power3.out', ...IR, onUpdate: () => { el.textContent = fmt(p.v); } }, t);
};
const swap = (el, txt, t) => {
  tl.set(el, { textContent: txt }, t);
  tl.fromTo(el, { opacity: .2, y: 6 }, { opacity: 1, y: 0, duration: .25, ease: 'power2.out', ...IR }, t);
};
const styleChip = (e, css) => Object.assign(e.style, Object.assign({ position: 'absolute', whiteSpace: 'nowrap', boxSizing: 'border-box', padding: '0 16px', height: '34px', lineHeight: '32px', fontSize: '20px', fontWeight: '800', borderRadius: '17px' }, css));

/* ---------- geometry ---------- */
const CX = 476, CY = 390, CW = 564, CH = 444, CELL = 68, GAP = 8, GX = 20, GY = 60;
const cellXY = (i) => [GX + (i % 7) * (CELL + GAP), GY + Math.floor(i / 7) * (CELL + GAP)];
const DUR = ['0:21', '0:34', '0:48', '0:15', '0:29', '0:52', '0:38'];

/* ---------- top status strip (replaced later by the gold pill) ---------- */
const strip = R3.card(30, 304, 1020, 48);
T(24, 10, 'Schedule · Daily 6:00 PM', 22, { parent: strip, color: 'rgba(255,255,255,.82)', lh: 28 });
T(556, 10, '@you.beats · Auto-publish on', 22, { parent: strip, w: 440, align: 'right', color: 'rgba(255,255,255,.6)', lh: 28 });

/* ---------- calendar ---------- */
const cal = R3.card(CX, CY, CW, CH, null, { borderRadius: '26px' });
const title = T(22, 12, 'NOV · Upload calendar', 26, { parent: cal, weight: 800, lh: 32 });
const sc = R3.chip(CW - 22 - 170, 10, '0 day streak', null, { parent: cal });
Object.assign(sc.style, { position: 'absolute', width: '170px', height: '36px', lineHeight: '34px', padding: '0', textAlign: 'center', fontSize: '20px', fontWeight: '800',
  whiteSpace: 'nowrap', borderRadius: '18px', background: 'rgba(255,255,255,.1)', border: '1px solid rgba(255,255,255,.22)', color: '#fff', boxSizing: 'border-box' });
const ul = mk('div', 'r3-el', { position: 'absolute', left: (CW - 22 - 170) + 'px', top: '47px', width: '170px', height: '3px', borderRadius: '2px', background: '#ff4d5e', transformOrigin: '0% 50%' }, cal);

const thumbs = [], ticks = [], dec = [];
for (let i = 0; i < 35; i++) {
  const [x, y] = cellXY(i), isDec = i >= 30;
  const ph = mk('div', '', { position: 'absolute', left: x + 'px', top: y + 'px', width: CELL + 'px', height: CELL + 'px', borderRadius: '14px',
    border: '1.5px dashed rgba(255,255,255,' + (isDec ? .1 : .2) + ')', boxSizing: 'border-box' }, cal);
  mk('div', '', { position: 'absolute', left: '8px', top: '5px', fontSize: '13px', fontWeight: '700', color: 'rgba(255,255,255,' + (isDec ? .22 : .32) + ')' }, ph,
    isDec ? (i === 30 ? 'Dec 1' : String(i - 29)) : String(i + 1));
  const th = R3.thumb(x, y, CELL, CELL, (i * 7) % 10, { parent: cal, play: false });
  Object.assign(th.style, { position: 'absolute', borderRadius: '14px', overflow: 'hidden' });
  mk('div', '', { position: 'absolute', left: '0', top: '0', right: '0', bottom: '0', background: 'linear-gradient(180deg,rgba(0,0,0,.05) 35%,rgba(0,0,0,.5))' }, th);
  if (i % 3 === 0) { [10, 22, 30, 16, 8].forEach((h, b) => mk('div', '', { position: 'absolute', left: (18 + b * 7) + 'px', top: (30 - h / 2) + 'px', width: '4px', height: h + 'px', borderRadius: '2px', background: 'rgba(255,255,255,.75)' }, th)); }
  if (i % 3 === 1) { mk('div', '', { position: 'absolute', left: '23px', top: '19px', width: '22px', height: '22px', borderRadius: '50%', border: '2px solid rgba(255,255,255,.85)', boxSizing: 'border-box' }, th); }
  mk('div', '', { position: 'absolute', left: '8px', top: '5px', fontSize: '13px', fontWeight: '800', color: '#fff', textShadow: '0 1px 3px rgba(0,0,0,.6)' }, th, isDec ? (i === 30 ? 'Dec 1' : String(i - 29)) : String(i + 1));
  if (isDec) { dec.push(th); continue; }
  mk('div', '', { position: 'absolute', left: '8px', bottom: '5px', fontSize: '11px', fontWeight: '700', color: 'rgba(255,255,255,.9)' }, th, DUR[i % 7]);
  const tk = mk('div', '', { position: 'absolute', right: '5px', bottom: '5px', width: '20px', height: '20px', borderRadius: '50%', background: '#27e58b', color: '#04210f',
    fontSize: '13px', fontWeight: '900', textAlign: 'center', lineHeight: '20px' }, th, '✓');
  thumbs.push(th); ticks.push(tk);
}

/* light-wave layer (clipped to the calendar) */
const clip = mk('div', '', { position: 'absolute', left: '0', top: '0', width: CW + 'px', height: CH + 'px', overflow: 'hidden', borderRadius: '26px', pointerEvents: 'none' }, cal);
const KX = 540 - CX, KY = 50 - CY, RR = 860;
const ring = mk('div', '', { position: 'absolute', left: (KX - RR) + 'px', top: (KY - RR) + 'px', width: (RR * 2) + 'px', height: (RR * 2) + 'px', borderRadius: '50%', pointerEvents: 'none',
  background: 'radial-gradient(circle closest-side, transparent 0%, transparent 78%, rgba(255,205,90,0) 80%, rgba(255,215,120,.26) 95%, rgba(255,245,200,.55) 99%, transparent 100%)' }, clip);
tl.set(ring, { autoAlpha: 0, scale: 380 / RR }, S);
const cellFx = [];
for (let i = 0; i < 30; i++) {
  const [x, y] = cellXY(i);
  const d = Math.hypot(x + CELL / 2 - KX, y + CELL / 2 - KY);
  const delay = Math.max(0, (d - 380) / 480 * 1.1);
  const ov = mk('div', '', { position: 'absolute', left: x + 'px', top: y + 'px', width: CELL + 'px', height: CELL + 'px', borderRadius: '14px',
    background: 'linear-gradient(135deg,rgba(255,244,200,.85),rgba(255,205,90,.3))', pointerEvents: 'none' }, clip);
  let sp = null;
  if (i % 3 === 1) {
    sp = mk('div', '', { position: 'absolute', left: (x + 30 + (i * 5) % 24) + 'px', top: (y + (i * 3) % 18 - 4) + 'px', width: '28px', height: '28px', pointerEvents: 'none',
      background: 'linear-gradient(90deg,rgba(255,255,255,0),#fff 50%,rgba(255,255,255,0)) center/100% 2px no-repeat, linear-gradient(0deg,rgba(255,255,255,0),#fff 50%,rgba(255,255,255,0)) center/2px 100% no-repeat' }, clip);
  }
  cellFx.push({ ov, sp, delay });
}

/* ---------- left column: vault + reach ---------- */
const vault = R3.card(30, 390, 420, 222);
T(24, 16, 'VAULT', 20, { parent: vault, weight: 800, color: 'rgba(255,255,255,.55)', ls: '3px', lh: 24 });
const rwrap = mk('div', '', { position: 'absolute', left: '24px', top: '58px', width: '120px', height: '120px' }, vault);
const rsvg = sv('svg', { width: 120, height: 120, viewBox: '0 0 120 120' }, rwrap);
sv('circle', { cx: 60, cy: 60, r: 50, fill: 'none', stroke: 'rgba(255,255,255,.14)', 'stroke-width': 10 }, rsvg);
const arc = sv('circle', { cx: 60, cy: 60, r: 50, fill: 'none', stroke: GOLD, 'stroke-width': 10, pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1, transform: 'rotate(-90 60 60)' }, rsvg);
const ringTxt = T(0, 43, '0%', 28, { parent: rwrap, w: 120, align: 'center', weight: 800, lh: 34 });
const posted = T(158, 44, '0', 54, { parent: vault, weight: 800, lh: 56 });
T(158, 110, 'videos posted', 22, { parent: vault, color: 'rgba(255,255,255,.55)', lh: 25 });
const latest = T(158, 143, '↳ no uploads yet', 22, { parent: vault, color: 'rgba(255,255,255,.85)', lh: 25 });
const ready = R3.chip(158, 178, '12 edits ready', null, { parent: vault });
styleChip(ready, { background: 'rgba(255,210,90,.18)', color: GOLD, border: '1px solid rgba(255,210,90,.5)' });

const reach = R3.card(30, 628, 420, 206);
T(24, 20, 'CHANNEL REACH · 30D', 20, { parent: reach, weight: 800, color: 'rgba(255,255,255,.55)', ls: '2px', lh: 24 });
const rnum = T(24, 54, '48,213', 68, { parent: reach, weight: 800, lh: 76, color: 'rgba(255,255,255,.88)' });
T(24, 142, 'views', 26, { parent: reach, color: 'rgba(255,255,255,.6)', lh: 30 });
const delta = R3.chip(236, 140, '▲ 2,399%', null, { parent: reach });
styleChip(delta, { background: 'rgba(80,255,160,.15)', color: '#5dffa8', border: '1px solid rgba(80,255,160,.45)' });

/* ---------- gold offer pill + dock ---------- */
const pw = mk('div', '', { position: 'absolute', left: CX + 'px', top: '304px', width: CW + 'px', height: '48px', display: 'flex', justifyContent: 'center' });
const pill = mk('div', 'r3-chip r3-el', { position: 'relative', left: '0', top: '0', height: '48px', lineHeight: '48px', padding: '0 24px 0 12px', fontSize: '24px', fontWeight: '800',
  color: '#2a1c00', borderRadius: '24px', whiteSpace: 'nowrap', background: 'linear-gradient(135deg,#ffe28a,#ffbf3a)', border: 'none', boxSizing: 'border-box',
  display: 'flex', alignItems: 'center', gap: '10px' }, pw,
  '<span style="display:inline-block;width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#2a1c00,#8a5d00)"></span>Feature request · @bigstage');
const dock = mk('div', 'r3-el', { position: 'absolute', left: (CX + CW / 2 - 7) + 'px', top: '383px', width: '14px', height: '14px', borderRadius: '50%', background: GOLD, border: '2px solid #2a1c00', boxSizing: 'border-box' });

