  { a: 0, b: 2, w: 96, st: .1, latest: 'hook test' },
  { a: 3, b: 6, w: 97, st: .06, latest: 'sample flip' },
  { a: 7, b: 13, w: 99, st: .05, latest: 'studio tour' },
  { a: 14, b: 20, w: 101, st: .04, latest: 'mashup #7' },
  { a: 21, b: 29, w: 105, st: .03, latest: 'BTS clip' }
];
WK.forEach((k) => {
  const t = W[k.w] - .05;
  R3.appear(thumbs.slice(k.a, k.b + 1), t, { y: 0, scale: .55, d: .42, stagger: k.st, ease: 'back.out(1.5)' });
  R3.ft(ticks.slice(k.a, k.b + 1), { scale: 0 }, { scale: 1, duration: .28, ease: 'back.out(2.6)', stagger: k.st }, t + .22);
  swap(latest, '↳ ' + k.latest, t + .3);
});

// streak chip rolls (non-overlapping)
const sfmt = (v) => Math.round(v) + ' day streak';
roll(sc, 22.98, .3, 0, 3, sfmt);
roll(sc, 23.30, .4, 3, 7, sfmt);
roll(sc, W[99] - .05, .6, 7, 14, sfmt);
