roll(posted, 23.15, .3, 0, 3, pfmt);
roll(posted, 23.45, .3, 3, 7, pfmt);
roll(posted, 24.25, .5, 7, 14, pfmt);
roll(posted, 25.20, .26, 14, 21, pfmt);
roll(posted, 25.50, .5, 21, 30, pfmt);

// w107 — vault settles, ring closes
const tV = W[107] - .05;
R3.draw(arc, tV, .9);
roll(ringTxt, tV, .9, 0, 100, (v) => Math.round(v) + '%', 'power2.inOut');
