const NS = 'http://www.w3.org/2000/svg';
const sv = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); return e; };
const A = (o) => Object.assign({ position: 'absolute' }, o);
const T = (i) => W[i] - 0.05;
const mk = R3.mk;

/* ============ HERO: porch camera feed (kept fully inside x 50..1030, y 308..684) ============ */
const CW = 980, CH = 376;
const camCard = R3.card(50, 308, CW, CH, null, { overflow: 'hidden', borderRadius: '26px', background: 'var(--sheen), #0b0e14' });

/* the feed itself lives in a zoom wrapper: the push-in is a digital zoom inside the camera frame,
   so no card ever leaves the stage */
const zoom = mk('div', '', A({ left: 0, top: 0, width: CW + 'px', height: CH + 'px' }), camCard);
tl.set(zoom, { transformOrigin: '442px 230px' }, S);

// static scene (night porch, warm key from upper-left)
mk('div', '', A({ left: 0, top: 0, width: CW + 'px', height: '250px',
  background: 'repeating-linear-gradient(180deg, rgba(0,0,0,.28) 0 2px, transparent 2px 26px), linear-gradient(180deg,#141a26,#1c2433)' }), zoom);
mk('div', '', A({ left: 0, top: '250px', width: CW + 'px', height: '126px',
  background: 'repeating-linear-gradient(90deg, rgba(0,0,0,.4) 0 2px, transparent 2px 78px), linear-gradient(180deg,#2a2218,#0f0c08)' }), zoom);
const door = mk('div', '', A({ left: '40px', top: '50px', width: '170px', height: '200px', borderRadius: '6px 6px 0 0',
  background: 'linear-gradient(160deg,#2e3442,#171b25)', border: '3px solid rgba(255,255,255,.07)', boxSizing: 'border-box' }), zoom);
mk('div', '', A({ left: '18px', top: '16px', width: '130px', height: '58px', borderRadius: '4px', border: '2px solid rgba(255,255,255,.06)', background: 'rgba(0,0,0,.18)' }), door);
mk('div', '', A({ left: '18px', top: '90px', width: '130px', height: '94px', borderRadius: '4px', border: '2px solid rgba(255,255,255,.06)', background: 'rgba(0,0,0,.18)' }), door);
mk('div', '', A({ left: '132px', top: '98px', width: '12px', height: '12px', borderRadius: '50%', background: '#caa35a' }), door);
mk('div', '', A({ left: '50px', top: '262px', width: '150px', height: '34px', borderRadius: '4px',
  background: 'repeating-linear-gradient(90deg,#3a342b 0 6px,#2a251e 6px 12px)' }), zoom);

// parcel (inside the zoom wrapper)
const parcel = mk('div', 'r3-el', A({ left: '320px', top: '120px', width: '340px', height: '210px', transformOrigin: '50% 100%' }), zoom);
mk('div', '', A({ left: '-10px', top: '188px', width: '370px', height: '36px', background: 'radial-gradient(ellipse at 50% 50%, rgba(0,0,0,.6), transparent 70%)' }), parcel);
mk('div', '', A({ left: 0, top: 0, width: '340px', height: '210px', borderRadius: '6px',
  background: 'repeating-linear-gradient(90deg, rgba(0,0,0,.035) 0 2px, transparent 2px 6px), linear-gradient(120deg,#f2c777 0%,#d29a4a 45%,#a8702d 100%)',
  boxShadow: 'inset -30px -20px 50px rgba(60,30,0,.45), inset 10px 10px 40px rgba(255,230,160,.35)' }), parcel);
mk('div', '', A({ left: 0, top: 0, width: '340px', height: '34px', borderBottom: '2px solid rgba(80,40,0,.35)', background: 'rgba(255,225,160,.18)', borderRadius: '6px 6px 0 0', boxSizing: 'border-box' }), parcel);
mk('div', '', A({ left: '258px', top: 0, width: '50px', height: '210px', background: 'linear-gradient(90deg, rgba(255,240,200,.55), rgba(230,200,140,.45))' }), parcel);
const lab = mk('div', '', A({ left: '22px', top: '72px', width: '218px', height: '112px', background: '#fbf8f1', borderRadius: '4px', boxShadow: '0 2px 6px rgba(0,0,0,.35)' }), parcel);
mk('div', '', A({ left: '12px', top: '8px', fontSize: '10px', fontWeight: 700, letterSpacing: '2px', color: '#8a8478', lineHeight: '12px' }), lab, 'FROM');
mk('div', '', A({ left: '12px', top: '22px', fontSize: '21px', fontWeight: 800, color: '#15110b', lineHeight: '26px', whiteSpace: 'nowrap' }), lab, 'HALO RECORDS');
const under = mk('div', '', A({ left: '12px', top: '50px', width: '150px', height: '3px', background: '#e8283c', transformOrigin: '0% 50%' }), lab);
mk('div', '', A({ left: '12px', top: '58px', fontSize: '12px', fontWeight: 600, color: '#4a453b', lineHeight: '16px', whiteSpace: 'nowrap' }), lab, 'Global distribution · 3 albums');
mk('div', '', A({ left: '12px', top: '84px', width: '194px', height: '18px',
  background: 'repeating-linear-gradient(90deg,#111 0 2px,transparent 2px 4px,#111 4px 5px,transparent 5px 8px,#111 8px 11px,transparent 11px 13px)' }), lab);
// detection brackets
const sv1 = sv('svg', { width: 372, height: 242, viewBox: '0 0 372 242' }, parcel);
Object.assign(sv1.style, { position: 'absolute', left: '-16px', top: '-16px', overflow: 'visible' });
const brk = sv('path', { d: 'M2 36 V2 H36 M336 2 H370 V36 M370 206 V240 H336 M36 240 H2 V206', fill: 'none', stroke: '#ffd25a', 'stroke-width': 4,
  'stroke-linecap': 'round', 'stroke-linejoin': 'round', pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 }, sv1);

// static overlays (key light, scanlines, vignette, top fade) stay fixed over the zooming feed
mk('div', '', A({ left: 0, top: 0, width: CW + 'px', height: CH + 'px', pointerEvents: 'none',
  background: 'radial-gradient(ellipse 75% 95% at 24% -8%, rgba(255,190,110,.34) 0%, rgba(255,190,110,.12) 45%, transparent 75%)' }), camCard);
mk('div', '', A({ left: 0, top: 0, width: CW + 'px', height: CH + 'px', pointerEvents: 'none',
  background: 'repeating-linear-gradient(0deg, rgba(255,255,255,.022) 0 1px, transparent 1px 4px), radial-gradient(ellipse at 50% 45%, transparent 55%, rgba(0,0,0,.6) 100%)' }), camCard);
mk('div', '', A({ left: 0, top: 0, width: CW + 'px', height: '60px', background: 'linear-gradient(180deg,rgba(0,0,0,.7),transparent)', pointerEvents: 'none' }), camCard);

// cam UI
const uiTitle = mk('div', 'r3-el', A({ left: '24px', top: '14px', fontSize: '22px', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '10px', lineHeight: '28px' }), camCard,
  '<i style="width:12px;height:12px;border-radius:50%;background:#ff4d5e;display:block"></i>Porch Cam · LIVE');
const uiTime = mk('div', 'r3-el', A({ left: '430px', top: '14px', fontSize: '22px', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', lineHeight: '28px' }), camCard,
  '21:47<span style="opacity:.55;margin-left:10px;font-weight:600">Nov 14</span>');
const uiBatt = mk('div', 'r3-el', A({ left: '856px', top: '14px', fontSize: '22px', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '8px', lineHeight: '28px' }), camCard,
  '<span style="position:relative;display:block;width:38px;height:18px;border:2px solid #fff;border-radius:5px;box-sizing:border-box"><i style="position:absolute;left:2px;top:2px;bottom:2px;width:67%;background:#3dff8b;border-radius:2px"></i><b style="position:absolute;right:-6px;top:3px;width:3px;height:8px;background:#fff;border-radius:0 2px 2px 0"></b></span>82%');
const uiCam = mk('div', 'r3-el', A({ left: '24px', top: '344px', fontSize: '16px', fontWeight: 600, color: 'rgba(255,255,255,.6)', whiteSpace: 'nowrap', lineHeight: '20px' }), camCard, 'Cam 2 · Front door');

// motion chip
const mchip = R3.chip(24, 72, 'Delivery detected', null, { parent: camCard });
Object.assign(mchip.style, { position: 'absolute', background: 'rgba(255,210,90,.96)', color: '#1b1204', fontSize: '18px', fontWeight: 800, padding: '8px 14px', whiteSpace: 'nowrap', lineHeight: '20px', borderRadius: '999px' });

// size meter
const meter = R3.card(850, 70, 112, 262, camCard, { borderRadius: '18px', background: 'var(--sheen), rgba(8,10,16,.78)' });
mk('div', '', A({ left: '18px', top: '26px', width: '10px', height: '210px', borderRadius: '5px', background: 'rgba(255,255,255,.16)' }), meter);
const fill = mk('div', '', A({ left: '18px', top: '26px', width: '10px', height: '210px', borderRadius: '5px', background: 'linear-gradient(0deg,#ff9a3c,#ffd25a)', transformOrigin: '50% 100%' }), meter);
tl.set(fill, { scaleY: 0.13 }, S);
const dotY = [22, 112, 202], labY = [18, 108, 198], labT = ['Major', 'Mid', 'Indie'];
const dots = [0, 1, 2].map((i) => mk('div', '', A({ left: '15px', top: dotY[i] + 'px', width: '16px', height: '16px', borderRadius: '50%', boxSizing: 'border-box',
  background: i === 2 ? '#ffffff' : 'rgba(255,255,255,.28)', border: '2px solid rgba(10,12,18,.9)' }), meter));
const labs = [0, 1, 2].map((i) => mk('div', '', A({ left: '40px', top: labY[i] + 'px', fontSize: '18px', fontWeight: 700, lineHeight: '24px', whiteSpace: 'nowrap',
  color: i === 2 ? '#fff' : 'rgba(255,255,255,.4)' }), meter, labT[i]));
// dots order: 0=Major(top) 1=Mid 2=Indie

// value chip (below the parcel, over the porch floor)
const vchip = R3.chip(420, 336, '$0K advance', null, { parent: camCard });
Object.assign(vchip.style, { position: 'absolute', background: 'rgba(61,255,139,.95)', color: '#04200f', fontSize: '18px', fontWeight: 800, padding: '8px 12px', whiteSpace: 'nowrap', lineHeight: '20px', borderRadius: '999px' });

/* ============ ORDER STRIP (y 698..762) ============ */
const strip = R3.card(50, 698, 980, 64, null, { borderRadius: '18px' });
mk('div', '', A({ left: '22px', top: '21px', fontSize: '19px', fontWeight: 600, color: 'rgba(255,255,255,.5)', lineHeight: '22px', whiteSpace: 'nowrap' }), strip, 'Deal flow');
const slotCss = { display: 'flex', alignItems: 'center', gap: '12px', padding: '0 14px', boxSizing: 'border-box', fontSize: '22px', fontWeight: 700, color: '#fff', borderRadius: '14px', width: '300px', height: '44px', top: '10px' };
const badge = (n) => `<span style="width:28px;height:28px;border-radius:50%;background:rgba(255,255,255,.14);display:flex;align-items:center;justify-content:center;font-size:16px">${n}</span>`;
const slot1 = mk('div', '', A(Object.assign({}, slotCss, { left: '150px', background: 'rgba(61,255,139,.14)', border: '1.5px solid rgba(61,255,139,.7)' })), strip,
  badge(1) + '<span>Offer</span><svg style="margin-left:auto" width="24" height="24" viewBox="0 0 24 24"><path d="M4 12.5l5 5L20 6.5" fill="none" stroke="#3dff8b" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/></svg>');
const slot2 = mk('div', '', A(Object.assign({}, slotCss, { left: '600px', background: 'rgba(255,255,255,.03)', border: '1.5px dashed rgba(255,255,255,.35)' })), strip,
  badge(2) + '<span>Prep</span><span style="margin-left:auto;font-size:16px;font-weight:600;color:rgba(255,255,255,.45)">Pending</span>');
mk('div', '', A({ left: '916px', top: '15px', fontSize: '28px', fontWeight: 800, color: '#fff', lineHeight: '34px', whiteSpace: 'nowrap' }), strip, '1/2');
const asv = sv('svg', { width: 980, height: 64, viewBox: '0 0 980 64' }, strip);
Object.assign(asv.style, { position: 'absolute', left: 0, top: 0, overflow: 'visible' });
const shaft = sv('path', { d: 'M584 32 H488', fill: 'none', stroke: '#ff4d5e', 'stroke-width': 5, 'stroke-linecap': 'round', pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 }, asv);
const head = sv('polygon', { points: '474,32 494,21 494,43', fill: '#ff4d5e' }, asv);

/* ============ LOCKED BUTTONS (y 774..826) ============ */
const lockSvg = '<svg width="20" height="22" viewBox="0 0 22 24"><rect x="2" y="10" width="18" height="13" rx="3" fill="currentColor"/><path d="M6 10V7a5 5 0 0 1 10 0v3" fill="none" stroke="currentColor" stroke-width="2.6"/></svg>';
const btns = ['Accept', 'Counter', 'Decline'].map((n, i) => {
  const e = R3.card(50 + i * 336, 774, 308, 52, null, { borderRadius: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '12px', fontSize: '24px', fontWeight: 700, color: 'rgba(255,255,255,.4)' });
  e.innerHTML = n + lockSvg;
  return e;
});
function deny(b, t) {
  tl.to(b, { color: 'rgba(255,110,125,.95)', borderColor: 'rgba(255,90,106,.7)', duration: .25 }, t);
  tl.to(b, { x: -10, duration: .06, ease: 'power1.out' }, t);
  tl.to(b, { x: 8, duration: .07, ease: 'power1.inOut' }, t + .06);
  tl.to(b, { x: -5, duration: .07, ease: 'power1.inOut' }, t + .13);
  tl.to(b, { x: 0, duration: .08, ease: 'power1.out' }, t + .2);
}

/* ============ TIMELINE ============ */
// w128: match cut into the feed, parcel settles
R3.appear(camCard, S + 0.05, { y: 0, scale: .96, d: .55, ease: 'power3.out' });
R3.appear(parcel, S + 0.2, { y: -70, scale: 1, d: .65, ease: 'back.out(1.3)' });
R3.appear([uiTitle, uiTime, uiBatt, uiCam], S + 0.3, { y: -8, scale: 1, d: .4, stagger: .07 });
// label starts soft
R3.ft(lab, { filter: 'blur(5px)', opacity: .55 }, { filter: 'blur(0px)', opacity: 1, duration: .6, ease: 'power2.out' }, T(132));

// w132: motion chip + brackets
R3.appear(mchip, T(132), { y: 10, scale: .9, d: .4 });
R3.draw(brk, T(132) + .05, .5);

// w136: size meter on, at Indie
R3.appear(meter, T(136), { x: 20, y: 0, scale: .96, d: .5 });

// w137: order strip lands
R3.appear(strip, T(137), { y: 20, d: .55 });
R3.appear(slot1, T(137) + .15, { y: 0, scale: .9, d: .4 });
R3.appear(slot2, T(137) + .3, { y: 0, scale: .9, d: .4 });

// w139: prep slot flags red
tl.to(slot2, { borderColor: 'rgba(255,90,106,.95)', backgroundColor: 'rgba(255,77,94,.10)', duration: .35 }, T(139));

// w140: reversed-order arrow
R3.draw(shaft, T(140), .35);
R3.ft(head, { autoAlpha: 0, scale: .4, svgOrigin: '476 32' }, { autoAlpha: 1, scale: 1, svgOrigin: '476 32', duration: .3, ease: 'back.out(2)' }, T(140) + .28);

// w142: locked buttons (rise in from just above their slot, staying inside the stage)
R3.appear(btns, T(142), { y: -10, scale: .94, d: .5, stagger: .09 });

// w147-152: each locked button is refused in turn
deny(btns[0], T(147));
deny(btns[1], T(150));
deny(btns[2], T(152));

// w157: meter jumps to Major, parcel grows, feed push-in begins
const mj = T(157);
tl.to(fill, { scaleY: 1, duration: .8, ease: 'power3.out' }, mj);
tl.to(labs[2], { color: 'rgba(255,255,255,.4)', duration: .3 }, mj);
tl.to(dots[1], { backgroundColor: '#ffd25a', duration: .2 }, mj + .2);
tl.to(dots[0], { backgroundColor: '#ffd25a', scale: 1.35, duration: .3, ease: 'back.out(2)' }, mj + .5);
tl.to(labs[0], { color: '#ffd25a', scale: 1.12, transformOrigin: '0% 50%', duration: .4, ease: 'back.out(1.6)' }, mj + .45);
tl.to(meter, { borderColor: 'rgba(255,210,90,.9)', duration: .4 }, mj + .4);
tl.to(parcel, { scale: 1.22, duration: .9, ease: 'back.out(1.4)' }, mj + .05);
// one continuous eased push onto the shipping label, done as two equal halves (in + out) of the feed zoom
R3.ft(zoom, { scale: 1, x: 0, y: 0 }, { scale: 1.5, x: 24, y: -21, duration: 1.2, ease: 'power2.in' }, mj + .02);
tl.fromTo(zoom, { scale: 1.5, x: 24, y: -21 }, { scale: 2, x: 48, y: -42, duration: 1.2, ease: 'power2.out', immediateRender: false }, mj + 1.22);

// w159: value chip ticks on
R3.appear(vchip, T(159), { y: 10, scale: .9, d: .4 });
R3.count(vchip, T(159), .9, 0, 250, { pre: '$', suf: 'K advance' });

// w160: label underline, then the push settles tight on it
R3.ft(under, { scaleX: 0 }, { scaleX: 1, duration: .4, ease: 'power3.out' }, T(160));

sec4:
const T = (i) => W[i] - 0.05;
const NS = 'http://www.w3.org/2000/svg';
const FONT = '"Inter","SF Pro Display","Helvetica Neue",Arial,sans-serif';
const mid = ctx.mid;

/* ---------- local DOM helpers ---------- */
const el = (parent, x, y, w, h, css, html, cls) => R3.mk('div', cls === undefined ? 'r3-el' : cls,
  Object.assign({ position: 'absolute', left: x + 'px', top: y + 'px', boxSizing: 'border-box', fontFamily: FONT, whiteSpace: 'nowrap' },
    w != null ? { width: w + 'px' } : {}, h != null ? { height: h + 'px' } : {}, css || {}), parent, html);
const flexC = { display: 'flex', alignItems: 'center', justifyContent: 'center' };
const svgIn = (parent, extra) => {
  const s = document.createElementNS(NS, 'svg');
  s.setAttribute('width', 1); s.setAttribute('height', 1);
  s.style.cssText = 'position:absolute;left:0;top:0;overflow:visible;pointer-events:none;' + (extra || '');
  parent.appendChild(s); return s;
};
const hair = (svg, d, color, w) => {
  const p = document.createElementNS(NS, 'path');
  const a = { d, fill: 'none', stroke: color, 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-linejoin': 'round',
    pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 };
  for (const k in a) p.setAttribute(k, a[k]);
  svg.appendChild(p); return p;
};
const INK = '#1b1a17';

/* ---------- camera: starts pushed in, one continuous pull-back at w219 ---------- */
tl.set(ctx.cam.el, { scale: 1.14, transformOrigin: '540px 567px' }, S);

/* ================= CONTRACT (becomes page Z) ================= */
const PX = 350, PY = 345, PW = 540, PH = 444;
const cg = el(mid, PX, PY, PW, PH, { transformOrigin: '0px 0px', zIndex: 200 }, '', '');
const uf = el(cg, 0, 0, PW, PH, { transformOrigin: '50% 0%' }, '', '');
const pg = el(uf, 0, 0, PW, PH, {
  borderRadius: '12px',
  background: 'linear-gradient(200deg,#fffaf0 0%,#f3eee1 48%,#e4ddcb 100%)',
  boxShadow: 'inset -2px 2px 0 rgba(255,190,130,.8), 0 34px 70px rgba(0,0,0,.55)'
});
const PHB = 'rgba(27,26,23,.26)';

// blurred placeholders for sender / advance / signature
const pS = el(uf, 24, 16, 400, 40, { background: PHB, filter: 'blur(5px)', borderRadius: '20px' });
const pA = el(uf, 24, 128, 230, 66, { background: PHB, filter: 'blur(6px)', borderRadius: '10px' });
const pSig = el(uf, 24, 408, 270, 14, { background: PHB, filter: 'blur(4px)', borderRadius: '7px' });

// title
const title = el(uf, 24, 66, 492, 38, { fontFamily: 'Georgia,"Times New Roman",serif', fontSize: '28px', fontWeight: 700, color: INK, lineHeight: '38px' }, 'Exclusive Recording Agreement');
const ul = el(uf, 24, 108, 450, 4, { background: '#e8283c', borderRadius: '2px', transformOrigin: '0 50%' });

// paperclip
const clipSvg = svgIn(uf, 'left:506px;top:4px');
const clip = hair(clipSvg, 'M8 52 V18 A9 9 0 0 1 26 18 V50 A12 12 0 0 1 2 50 V24', '#8e8878', 3.5);

// sender chip
const sender = el(uf, 24, 16, null, 40, Object.assign({ background: INK, color: '#fff', borderRadius: '20px', padding: '0 16px 0 6px',
  display: 'flex', alignItems: 'center', gap: '10px', fontSize: '20px', fontWeight: 600 }),
  '<span style="width:28px;height:28px;border-radius:50%;background:#ffb070;color:#1b1a17;font-size:13px;font-weight:800;display:flex;align-items:center;justify-content:center">JR</span>From: J. Reyes · A&amp;R, Halo Records');

// advance
const advLab = el(uf, 24, 124, null, 18, { fontSize: '15px', letterSpacing: '.16em', fontWeight: 700, color: '#8a8374', lineHeight: '18px' }, 'ADVANCE · RECOUPABLE');
const advNum = el(uf, 24, 146, 270, 48, { fontSize: '46px', fontWeight: 800, color: INK, lineHeight: '48px', letterSpacing: '-.02em', fontVariantNumeric: 'tabular-nums' }, '$0');
const meta1 = el(uf, 296, 134, 240, 22, { textAlign: 'right', fontSize: '18px', fontWeight: 600, color: '#5c574b', lineHeight: '22px' }, 'Territory · Worldwide');
const meta2 = el(uf, 296, 164, 240, 22, { textAlign: 'right', fontSize: '18px', fontWeight: 600, color: '#5c574b', lineHeight: '22px' }, 'Effective · Nov 14');
const divider = el(uf, 24, 200, 492, 2, { background: 'rgba(27,26,23,.25)', transformOrigin: '0 50%' });
const rule = el(uf, 480, 208, 2, 172, { background: 'rgba(232,40,60,.55)', transformOrigin: '50% 0' });

// clause rows
const rowY = [212, 256, 300, 344];
const clauses = [
  { c: '#ffe14a', t: '§4.2 Recoupment of all advances', w: 420, pw: 400 },
  { c: '#ff9cc8', t: '§7 Cross-collateralization', w: 390, pw: 350 },
  { c: '#8ccfff', t: '§9 360 participation · 25%', w: 360, pw: 420 },
  { c: '#86f0a4', t: 'Term: 5 albums / 7 years', w: 340, pw: 310 }
];
const phs = clauses.map((c, j) => el(uf, 24, rowY[j] + 8, c.pw, 20, { background: PHB, filter: 'blur(4px)', borderRadius: '10px' }));
const hls = clauses.map((c, j) => el(uf, 24, rowY[j], c.w, 36, { background: c.c, borderRadius: '6px', transformOrigin: '0 50%' }));
const txs = clauses.map((c, j) => el(uf, 36, rowY[j] + 5, null, 26, { fontSize: '22px', fontWeight: 700, color: INK, lineHeight: '26px' }, c.t));
const qs = clauses.map((c, j) => el(uf, 498, rowY[j] + 4, 28, 28, Object.assign({ borderRadius: '50%', background: '#e8283c', color: '#fff', fontSize: '18px', fontWeight: 800 }, flexC), '?'));

// signature row
const sigLab = el(uf, 24, 404, null, 22, { fontSize: '18px', fontWeight: 600, color: '#5c574b', lineHeight: '22px' }, 'Artist signature');
const sigLine = el(uf, 192, 424, 104, 2, { background: INK, transformOrigin: '0 50%' });
